require_once dirname(__DIR__).'/config.php';$conn=db();$eventId=(int)($_GET['event_id']??0);$status=trim($_GET['status']??'');$search=trim($_GET['search']??'');$where=[];$params=[];$types='';if($eventId){$where[]='a.event_id=?';$params[]=$eventId;$types.='i';}if($status){$where[]='a.attendance_status=?';$params[]=$status;$types.='s';}if($search){$where[]='(s.student_no LIKE CONCAT("%",?,"%") OR s.first_name LIKE CONCAT("%",?,"%") OR s.last_name LIKE CONCAT("%",?,"%"))';$params[]=$search;$params[]=$search;$params[]=$search;$types.='sss';}$sql="SELECT a.*,e.event_name,e.event_date,s.student_no,s.first_name,s.last_name,s.course,s.year_level,s.section FROM event_attendance a JOIN events e ON e.id=a.event_id JOIN students s ON s.id=a.student_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY e.event_date DESC,a.attendance_id DESC LIMIT 1000";$stmt=$conn->prepare($sql);if($params){$bind=[$types];foreach($params as $i=>$v)$bind[]=&$params[$i];call_user_func_array([$stmt,'bind_param'],$bind);}$stmt->execute();$rows=$stmt->get_result();$events=$conn->query('SELECT id,event_name,event_date FROM events ORDER BY event_date DESC');$pageTitle='Attendance Reports';ob_start();?><div class="space-y-6"><div class="rounded-2xl bg-white p-5 shadow"><form class="grid gap-3 md:grid-cols-4"><select name="event_id" class="rounded border px-3 py-2"><option value="0">All events</option><?php while($e=$events->fetch_assoc()):?><option value="<?php echo (int)$e['id'];?>" <?php echo $eventId===$e['id']?'selected':'';?>><?php echo h($e['event_name'].' Â· '.$e['event_date']);?></option><?php endwhile;?></select><select name="status" class="rounded border px-3 py-2"><option value="">All statuses</option><?php foreach(['PRESENT','ABSENT','LATE','EXCUSED','INCOMPLETE'] as $x):?><option <?php echo $status===$x?'selected':'';?>><?php echo $x;?></option><?php endforeach;?></select><input name="search" value="<?php echo h($search);?>" placeholder="Student ID or name" class="rounded border px-3 py-2"><button class="rounded bg-slate-900 px-4 py-2 text-white">Filter</button></form></div><div class="rounded-2xl bg-white p-5 shadow"><div class="mb-4 text-lg font-semibold">Student attendance</div><div class="overflow-x-auto"><table class="min-w-full text-sm"><thead><tr class="border-b text-left"><th class="px-2 py-2">Student</th><th class="px-2 py-2">Event / Date</th><th class="px-2 py-2">In</th><th class="px-2 py-2">Out</th><th class="px-2 py-2">Status</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr class="border-b"><td class="px-2 py-3"><div class="font-medium"><?php echo h($r['last_name'].', '.$r['first_name']);?></div><div class="text-xs text-slate-500"><?php echo h($r['student_no'].' Â· '.($r['course']??'').' '.($r['section']??''));?></div></td><td class="px-2 py-3"><?php echo h($r['event_name']);?><div class="text-xs text-slate-500"><?php echo h($r['event_date']);?></div></td><td class="px-2 py-3"><?php echo $r['scan_in']?h(date('g:i A',strtotime($r['scan_in']))):'--';?></td><td class="px-2 py-3"><?php echo $r['scan_out']?h(date('g:i A',strtotime($r['scan_out']))):'--';?></td><td class="px-2 py-3"><span class="rounded-full bg-slate-100 px-2 py-1 text-xs"><?php echo h($r['attendance_status']);?></span></td></tr><?php endwhile;?></tbody></table></div></div></div><?php $content=ob_get_clean();include __DIR__.'/_layout.php';
